{
  "title": "异兽之森的秘密",
  "scene": "你站在一片古老而神秘的森林入口，四周弥漫着淡淡的雾气。森林深处传来了奇怪的叫声，似乎有异兽在徘徊。入口附近有一块古老的石碑，上面刻着一些模糊的文字和图案。不远处，一群部落的猎人正紧张地讨论着什么，他们的装备看起来非常简陋。森林的另一边，一棵巨大的古树矗立着，树干上缠绕着一条细长的藤蔓，藤蔓上挂着几颗闪耀的珠子。",
  "goal": "找到传说中的上古神器",
  "clue": "石碑上的文字和图案",
  "choices": [
    {
      "id": "A",
      "text": "接近猎人，询问他们的意见",
      "outcome": "猎人们警惕地看了看你，告诉你森林里有危险的异兽。他们愿意带你绕路，但你需要帮助他们捕捉一只小兽作为交换。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "直接进入森林深处",
      "outcome": "你勇敢地进入了森林深处，但很快遇到了一只凶猛的异兽。你试图躲避，但异兽的速度太快，你被逼到了一棵大树下。幸好异兽对你的兴趣不大，最终它离开了。你浪费了一些时间，但没有受伤。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "仔细查看石碑上的文字和图案",
      "outcome": "你仔细观察石碑上的文字和图案，发现其中提到了古树的藤蔓和闪耀的珠子。根据石碑的指引，你沿着藤蔓找到了一颗特殊的珠子，这颗珠子正是传说中的上古神器。你成功地将它带回了部落。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
